    cb=split(range(W),dcs,W)
    tr=max(rb,key=lambda b:(sum(1 for r in b for c in range(W) if c not in dcs and inp[r][c]!=bg)))
    tc=max(cb,key=lambda b:(sum(1 for r in tr for c in b if r not in drs and inp[r][c]!=bg)))
    T={(r,c):inp[r][c] for r in tr for c in tc}
    thr,thc=(tr[0],len(tr)),(tc[0],len(tc))
    out=[row[:] for row in inp]
    for rr in rb:
        for cc2 in cb:
            off_r=rr[0]-thr[0]; off_c=cc2[0]-thc[0]
            ph=(thr[1]-thr[0])+1; pc=(thc[1]-thc[0])+1
            for r in range(rr[0],rr[1]+1):
                for c in range(cc2[0],cc2[1]+1):
                    out[r][c]=T[(r-off_r)%ph][(c-off_c)%pc]
    return out

