from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def bands(segs,n):
    out=[]; start=None
    for i,d in enumerate(segs+[None]):
        if start is None: start=d+1 if d is not None else 0
        elif d is not None: out.append((start,d-1)); start=d+1
    if start is not None: out.append((start,n-1))
    return out

def solve(inp):
    H=len(inp);W=len(inp[0])
    drs=sorted([r for r in range(H) if len(set(inp[r]))==1])
    dcs=sorted([c for c in range(W) if len({inp[r][c] for r in range(H)})==1])
    bgc=Counter(x for row in inp for x in row).most_common(1)[0][0]
    # divider lines: full constant lines whose color != dominant bg
    drs=[r for r in drs if inp[r][0]!=bgc]
    dcs=[c for c in dcs if inp[0][c]!=bgc]
    def score(r,c):
        return 1 if inp[r][c]!=bgc else 0
    def cnt(rows,cols):
        return sum(score(r,c) for r in rows for c in cols)
    rb=bands(drs,H); cb=bands(dcs,W)
    tr=max(rb,key=lambda b:cnt(b,(0,W)))
    tc=max(cb,key=lambda b:cnt(tr,b))
    ph=tr[1]-tr[0]+1; pc=tc[1]-tc[0]+1
    pat=[[inp[tr[0]+i][tc[0]+j] for j in range(pc)] for i in range(ph)]
    out=[row[:] for row in inp]
    for rr in rb:
        for cc2 in cb:
            for i in range(rr[1]-rr[0]):
                for j in range(cc2[1]-cc2[0]):
                    out[rr[0]+i][cc2[0]+j]=pat[i%ph][j%pc]
    return out

